import{c as e,Q as a,j as n,m as i}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Claude Tag Agent Identity: provisioned with its own credentials in Slack","description":"","frontmatter":{"url":"https://x.com/ClaudeDevs/status/2069895377080443271","title":"Claude Tag Agent Identity: provisioned with its own credentials in Slack","author":"ClaudeDevs (Anthropic Official)","archived":"2026-06-25T00:00:00.000Z","category":"deep-application","handle":"@ClaudeDevs","published":"2026-06-25T00:00:00.000Z","score":7.95,"stats":"2841❤ · 156 retweets","tags":["claude-tag","slack","agent-identity","credential-isolation","enterprise","mcp"],"type":"tweet-thread"},"headers":[],"relativePath":"research/tweets/2026-06-25-@ClaudeDevs-443271.md","filePath":"research/tweets/2026-06-25-@ClaudeDevs-443271.md","lastUpdated":1785909234000}'),s={name:"research/tweets/2026-06-25-@ClaudeDevs-443271.md"};function d(r,t,o,l,c,h){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="claude-tag-agent-identity-provisioned-with-its-own-credentials-in-slack-—-claudedevs" tabindex="-1">Claude Tag Agent Identity: provisioned with its own credentials in Slack — @ClaudeDevs <a class="header-anchor" href="#claude-tag-agent-identity-provisioned-with-its-own-credentials-in-slack-—-claudedevs" aria-label="Permalink to &quot;Claude Tag Agent Identity: provisioned with its own credentials in Slack — @ClaudeDevs&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/ClaudeDevs/status/2069895377080443271" target="_blank" rel="noreferrer">https://x.com/ClaudeDevs/status/2069895377080443271</a><strong>類別</strong>：deep-application <strong>統計</strong>：2841❤ · 156 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>When Claude is working in a channel with four people, whose credentials does it use?</p><p>The answer: its own. When tagging Claude, Claude gets provisioned like any other teammate, with its own credentials.</p><p>We call this access model &quot;agent identity&quot;. Here&#39;s how it works: 🧵</p><p>Agent identity means:</p><ul><li>Claude gets its own Slack credentials (not borrowing from any human)</li><li>Provisioned automatically when tagged (like onboarding a new team member)</li><li>Access is scoped to what Claude needs, not inherited from the human who tagged it</li><li>Separation of credentials prevents privilege escalation via Claude</li></ul><p>This is the new standard for how agents authenticate in collaborative environments. Instead of &quot;which human&#39;s token should the agent borrow?&quot;, the question becomes &quot;what identity does the agent have?&quot;</p><p>Internal usage: Anthropic&#39;s own Claude Tag is used for 65% of product PRs that get merged, operating with this independent credential model.</p><p>Access model comparison:</p><ul><li>Old pattern: Agent uses human&#39;s OAuth token (risk: full human privileges)</li><li>New pattern: Agent identity with scoped credentials (minimum necessary access)</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>直接適用企業 Claude Code 整合；credential isolation 模式對 subagent-strategy 有影響</td></tr><tr><td>B. 創新性 (20%)</td><td>9/10</td><td>Agent Identity 模型定義了新一代 agent auth 架構</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>官方聲明 + 65% PR 數據，但無獨立驗證</td></tr><tr><td>D. 技術深度 (15%)</td><td>8/10</td><td>明確解釋 credential scoping 架構</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>Slack 特定，但 agent identity 原則通用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.95/10</strong></td><td>9×0.3+9×0.2+6×0.2+8×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule（subagent-strategy.md Agent Input Security + MCP auth isolation 關聯；見 mcp-auth-isolation 提案） <strong>理由</strong>：Agent Identity 是 credential-from-human 反模式的官方解法，應補充到 subagent-strategy.md MCP auth 討論</p>',17)])])}const p=e(s,[["render",d]]);export{g as __pageData,p as default};
